//https://leetcode.com/problems/capacity-to-ship-packages-within-d-days/
class Solution {
public:
    int need_days(vector<int> &weights, int val){
        int d = 0;
        int sum = 0;
        for(auto a: weights){
            sum += a;
            if(sum > val){
                d++;
                sum = a;
            }
        }
        d++;
        return d;
    }
    int shipWithinDays(vector<int>& weights, int days) {
        int max_val = accumulate(weights.begin(), weights.end(), 0);
        int min_val = *max_element(weights.begin(), weights.end());

        while(min_val <= max_val){
            int mid_val = (max_val - min_val)/2 + min_val;
            int need = need_days(weights, mid_val);
            if(need > days){
                min_val = mid_val+1;
            }else{
                max_val = mid_val-1;
            }
        }
        return max_val + 1;
    }
};
